def find_least_prime():
    """Find the least prime number which is the sum of two distinct positive perfect squares."""
    n = 2  # Start with the smallest prime number
    while True:
        for i in range(1, n):
            for j in range(i + 1, n):
                if i**2 + j**2 == n:
                    if is_prime(n):
                        return n
        n += 1

